// Baut aus allen Buchungen eine CSV-Datei (gleiche Spalten wie der manuelle
// CSV-Export in buchungen-uebersicht.html) und hängt sie als Binärdatei an.
const bookings = $input.all().map(item => item.json);

const headers = ['ID','Status','Name','E-Mail','Telefon','Firma','Veranstaltungsdatum','Uhrzeit','Uhrzeit Ende','Gäste','Kugeln/Gast','Ort/Event','Straße','PLZ','Stadt','Entfernung (km)','Wunschsorten','Notizen (E-Mail)','Eigene Notizen','Angebot URL','Angebot Vorlage','Rechnung URL','Erstellt am','Aktualisiert am'];

function esc(field) {
  const str = (field === undefined || field === null) ? '' : field.toString();
  if (str.includes(',') || str.includes('\n') || str.includes('"')) {
    return '"' + str.replace(/"/g, '""') + '"';
  }
  return str;
}

let csv = headers.join(',') + '\n';
for (const b of bookings) {
  const row = [
    b.id, b.status, b.name, b.email, b.phone, b.company, b.date, b.time, b.timeEnd,
    b.guests, b.kugelPerGuest, b.location, b.street, b.plz, b.city, b.distance,
    b.wunschsorten, b.notizen, b.eigeneNotizen, b.angebotUrl, b.angebotVorlage,
    b.rechnungUrl, b.erstelltAm, b.aktualisiertAm
  ].map(esc);
  csv += row.join(',') + '\n';
}

const today = new Date().toISOString().split('T')[0];
const filename = `eisfavorite-backup-${today}.csv`;
const buffer = Buffer.from('\ufeff' + csv, 'utf-8');

const binaryData = await this.helpers.prepareBinaryData(buffer, filename, 'text/csv');

return [{
  json: { count: bookings.length, filename, date: today },
  binary: { data: binaryData }
}];

